class Solution {
public:
    string alienOrder(vector<string>& words) {
        unordered_map<char, unordered_set<char>> adj;
        unordered_map<char, int> indegree;
        for (const string& w : words) {
            for (char c : w) {
                if (!indegree.count(c)) {
                    indegree[c] = 0;
                    adj[c] = unordered_set<char>();
                }
            }
        }
        for (size_t i = 0; i + 1 < words.size(); ++i) {
            const string& w1 = words[i];
            const string& w2 = words[i + 1];
            size_t minLen = min(w1.size(), w2.size());
            if (w1.size() > w2.size() && w1.substr(0, minLen) == w2.substr(0, minLen)) {
                return "";
            }
            for (size_t j = 0; j < minLen; ++j) {
                if (w1[j] != w2[j]) {
                    if (!adj[w1[j]].count(w2[j])) {
                        adj[w1[j]].insert(w2[j]);
                        indegree[w2[j]]++;
                    }
                    break;
                }
            }
        }
        queue<char> q;
        for (const auto& pair : indegree) {
            if (pair.second == 0) q.push(pair.first);
        }
        string res = "";
        while (!q.empty()) {
            char c = q.front();
            q.pop();
            res += c;
            for (char nxt : adj[c]) {
                if (--indegree[nxt] == 0) q.push(nxt);
            }
        }
        return res.size() == indegree.size() ? res : "";
    }
};

class Solution {
    public String alienOrder(String[] words) {
        Map<Character, Set<Character>> adj = new HashMap<>();
        Map<Character, Integer> indegree = new HashMap<>();
        for (String w : words) {
            for (char c : w.toCharArray()) {
                adj.putIfAbsent(c, new HashSet<>());
                indegree.putIfAbsent(c, 0);
            }
        }
        for (int i = 0; i < words.length - 1; i++) {
            String w1 = words[i], w2 = words[i + 1];
            int minLen = Math.min(w1.length(), w2.length());
            if (w1.length() > w2.length() && w1.startsWith(w2)) return "";
            for (int j = 0; j < minLen; j++) {
                char c1 = w1.charAt(j), c2 = w2.charAt(j);
                if (c1 != c2) {
                    if (adj.get(c1).add(c2)) {
                        indegree.put(c2, indegree.get(c2) + 1);
                    }
                    break;
                }
            }
        }
        Queue<Character> q = new ArrayDeque<>();
        for (char c : indegree.keySet()) {
            if (indegree.get(c) == 0) q.add(c);
        }
        StringBuilder sb = new StringBuilder();
        while (!q.isEmpty()) {
            char c = q.poll();
            sb.append(c);
            for (char next : adj.get(c)) {
                int deg = indegree.get(next) - 1;
                indegree.put(next, deg);
                if (deg == 0) q.add(next);
            }
        }
        return sb.length() == indegree.size() ? sb.toString() : "";
    }
}

var alienOrder = function(words) {
    const adj = new Map();
    const indegree = new Map();
    for (const w of words) {
        for (const c of w) {
            if (!adj.has(c)) adj.set(c, new Set());
            if (!indegree.has(c)) indegree.set(c, 0);
        }
    }
    for (let i = 0; i < words.length - 1; i++) {
        const w1 = words[i], w2 = words[i + 1];
        const minLen = Math.min(w1.length(), w2.length());
        if (w1.length() > w2.length() && w1.slice(0, minLen) === w2.slice(0, minLen)) {
            return "";
        }
        for (let j = 0; j < minLen; j++) {
            if (w1[j] !== w2[j]) {
                if (!adj.get(w1[j]).has(w2[j])) {
                    adj.get(w1[j]).add(w2[j]);
                    indegree.set(w2[j], indegree.get(w2[j]) + 1);
                }
                break;
            }
        }
    }
    const q = [];
    for (const [c, deg] of indegree.entries()) {
        if (deg === 0) q.push(c);
    }
    const res = [];
    let head = 0;
    while (head < q.length) {
        const c = q[head++];
        res.push(c);
        for (const next of adj.get(c)) {
            const deg = indegree.get(next) - 1;
            indegree.set(next, deg);
            if (deg === 0) q.push(next);
        }
    }
    return res.length === indegree.size ? res.join("") : "";
};
